def compress(chars):
    res = []
    i = 0
    while i < len(chars):
        ch = chars[i]
        count = 0
        while i < len(chars) and chars[i] == ch:
            count += 1
            i += 1
        res.append(ch)
        if count > 1:
            res.extend(list(str(count)))
    for j in range(len(res)): chars[j] = res[j]
    return len(res)

